<script setup>
import {watch,ref,onUnmounted} from 'vue';import axios from 'axios';import {message} from '../art';import {useForm,Head,usePage,Link} from '@inertiajs/vue3';import RoundBuilder from '../Components/RoundBuilder.vue';import SubjectPicker from '../Components/SubjectPicker.vue';import Errors from '../Components/Errors.vue';import {art,modes} from '../art';
const props=defineProps({catalog:Object,freshSubjects:Array,freshPreferences:Object,activeCatch:Number}),page=usePage();
const mode=()=>new URL(page.url,'http://local').searchParams.get('mode')||'fresh';
const form=useForm({mode:['fresh','tutor','exam'].includes(mode())?mode():'fresh',count:20,subjects:[...(props.freshSubjects||props.catalog.subjects)],topics:[],topic_scope:'all',difficulty:'All',pool:'all',seed:Math.floor(Math.random()*4294967296),balance:false,minutes:30,fresh_unseen:props.freshPreferences?.fresh_unseen??7,fresh_balance:props.freshPreferences?.fresh_balance??true});
watch(()=>page.url,()=>{if(['fresh','tutor','exam'].includes(mode()))form.mode=mode()});
const catchPreview=ref(null),catchError=ref(''),checking=ref(false);let catchTimer,seq=0;
watch(()=>[form.mode,form.subjects.slice(),form.fresh_unseen,form.fresh_balance],()=>{clearTimeout(catchTimer);const id=++seq;catchPreview.value=null;catchError.value='';if(form.mode!=='fresh')return;checking.value=true;catchTimer=setTimeout(async()=>{try{const r=await axios.post('/fresh-catch/preview',form.data());if(id===seq)catchPreview.value=r.data}catch(e){if(id===seq)catchError.value=message(e)}finally{if(id===seq)checking.value=false}},350)},{deep:true,immediate:true});
onUnmounted(()=>{clearTimeout(catchTimer);seq++});
function start(){form.post('/attempts')}
</script>
<template><Head title="Practice"/><div class="page-title"><div><p class="eyebrow">Choose your round</p><h1>{{modes[form.mode]}}</h1><p>{{form.mode==='exam'?'A timed challenge, with feedback at the finish.':form.mode==='tutor'?'A guided round, with feedback after every answer.':'Ten new or previously missed questions to keep you moving.'}}</p></div><img class="portrait" :src="art[form.mode==='fresh'?'temaki':form.mode==='exam'?'wasabi':'maki']" alt="Practice sushi character"></div>
<div class="panel"><Errors :errors="form.errors"/><template v-if="form.mode==='fresh'"><SubjectPicker :subjects="catalog.subjects" v-model="form.subjects"/><section class="inset spaced"><h2>Choose your catch</h2><label>Preferred mix: {{form.fresh_unseen}} unseen + {{10-form.fresh_unseen}} previously missed<input type="range" min="0" max="10" step="1" v-model.number="form.fresh_unseen"></label><label class="check"><input type="checkbox" v-model="form.fresh_balance">Spread questions across my subjects</label><p class="muted">If one pool is short, the other fills the ten. Subject coverage is balanced where available. With more than ten subjects, each catch samples a selection.</p><p v-if="checking" role="status">Checking your catch…</p><p v-else-if="catchError" class="error" role="alert">{{catchError}}</p><div v-else-if="catchPreview" aria-live="polite"><strong>This catch: {{catchPreview.unseen}} unseen + {{catchPreview.missed}} previously missed</strong><div class="chips"><span v-for="(n,s) in catchPreview.coverage" :key="s">{{s}} · {{n}}</span></div></div></section><Link v-if="activeCatch" class="button primary" :href="'/attempts/'+activeCatch">Resume your unfinished catch</Link><button v-else class="primary" :disabled="!form.subjects.length||form.processing||checking||!catchPreview" @click="start">Start or resume Fresh Catch</button><p class="muted">An unfinished catch resumes with its original questions.</p></template><RoundBuilder v-else :key="form.mode" :form="form" :catalog="catalog" :busy="form.processing" @start="start"/></div></template>
